data.script:
function check(v,m){if(!v)throw new Error(m);}
const a=ActionGroup.find('BAAAAAAAAAAAAAAAA'),b=ActionGroup.find('?AAAAAAAAAAAAAAA');
check(a && b && a.uuid!==b.uuid,'distinct colliding groups');
check(a.actions.some(x=>x.name==='QA Collision verify'),'first membership');
check(!a.actions.some(x=>x.name==='QA Collision member'),'no cross membership');
check(b.actions.some(x=>x.name==='QA Collision member'),'second membership');
check(ActionGroup.getAll().filter(x=>x.uuid===a.uuid).length===1,'unique first identity');
check(ActionGroup.getAll().filter(x=>x.uuid===b.uuid).length===1,'unique second identity');
editor.setText('Group collision passed café 🐼\n'+a.uuid+'\n'+b.uuid);draft.update();
